    let acrossPx = input.lineMetrics0.y;
    let segmentLengthPx = input.lineMetrics0.z;
    let halfThicknessPx = input.lineMetrics0.w;

    let dashSize = input.lineMetrics1.x;
    let gapSize = input.lineMetrics1.y;
    let dashOffset = input.lineMetrics1.z;
    let featherPx = input.lineMetrics1.w;
    let aaWidthPx = input.antialias.x;
    let aaPower = input.antialias.y;
    let transitionPx = max(featherPx, aaWidthPx);

    let clampedAlongPx = clamp(alongPx, 0.0, segmentLengthPx);
    let bodyDistancePx = abs(acrossPx) - halfThicknessPx;
